/**
 * Generate reference/rest-api-index.mdx from the Drone Agent's route table.
 *
 * Input: ADOSDroneAgent/docs/api-surface.md (itself generated by
 * ADOSDroneAgent/scripts/gen-api-surface.py). Pass a path as the first CLI
 * argument to read a different copy.
 *
 * Usage (from Documentation/):
 *   npm --prefix scripts run gen:api
 *   npm --prefix scripts run gen:api -- /path/to/api-surface.md
 *
 * Parsing: every `## ` heading opens a section. Rows of the form
 * `| METHOD | \`path\` | notes |` become routes tagged with that section's
 * listener. Two-column tables (the "Not an HTTP route" section) are carried
 * through as-is.
 *
 * Grouping rule (deterministic):
 *   - `/api/vN/<area>/...`  groups by the first three segments (`/api/v1/ground-station`)
 *   - `/api/<area>/...`     groups by the first two segments (`/api/plugins`)
 *   - anything else         groups by the first segment (`/whep`, `/hls`, `/v1`)
 *   - `/`                   groups as `/`
 *   A path parameter segment (`{name}`, `{*name}`) ends the prefix early.
 *   Groups holding fewer than MIN_GROUP routes fold into one "Other routes"
 *   table, so single-route prefixes do not each get a heading.
 * Groups sort by prefix (code-point order), "Other routes" last. Rows sort by
 * path, then by METHOD_ORDER.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const MIN_GROUP = 3;
const METHOD_ORDER = ["GET", "POST", "PUT", "PATCH", "DELETE", "WS"];
const OTHER = "Other routes";

const DEFAULT_INPUT = fileURLToPath(
  new URL("../../ADOSDroneAgent/docs/api-surface.md", import.meta.url),
);
const OUTPUT = fileURLToPath(new URL("../reference/rest-api-index.mdx", import.meta.url));

interface Route {
  method: string;
  path: string;
  notes: string;
  servedBy: string;
}

interface Section {
  title: string;
  label: string;
  rows: string[][];
}

const cliArg = process.argv[2];
const input = cliArg ? resolve(process.cwd(), cliArg) : DEFAULT_INPUT;
const source = readFileSync(input, "utf-8").replace(/\r\n/g, "\n");

/**
 * Escape text for an MDX table cell, leaving inline code spans intact.
 * Em and en dashes and the `--` stand-in become a spaced hyphen.
 */
function cell(s: string): string {
  return s
    .replace(/\s*[\u2014\u2013]\s*/g, " - ")
    .replace(/\s--\s/g, " - ")
    .split("`")
    .map((part, i) =>
      i % 2 === 1
        ? part.replace(/\|/g, "\\|")
        : part
            .replace(/\{/g, "\\{")
            .replace(/\}/g, "\\}")
            .replace(/</g, "&lt;")
            .replace(/\|/g, "\\|"),
    )
    .join("`");
}

/** Split a markdown table row into trimmed cells. */
function splitRow(line: string): string[] {
  return line
    .trim()
    .replace(/^\|/, "")
    .replace(/\|$/, "")
    .split("|")
    .map((c) => c.trim());
}

/** Short label for a section heading: "Native (`ados-control` on :8080)". */
function sectionLabel(title: string): string {
  const [name, rest] = title.split(/\s*\u2014\s*|\s+--\s+/);
  return rest ? `${name.trim()} (${rest.trim()})` : name.trim();
}

const sections: Section[] = [];
let current: Section | null = null;
for (const line of source.split("\n")) {
  const heading = /^##\s+(.+)$/.exec(line);
  if (heading) {
    current = { title: heading[1].trim(), label: sectionLabel(heading[1].trim()), rows: [] };
    sections.push(current);
    continue;
  }
  if (!current || !line.trim().startsWith("|")) continue;
  const cells = splitRow(line);
  if (cells.every((c) => /^-{3,}$/.test(c))) continue;
  current.rows.push(cells);
}

const routes: Route[] = [];
const extras: { title: string; header: string[]; rows: string[][] }[] = [];
for (const section of sections) {
  const [header, ...body] = section.rows;
  if (!header) continue;
  if (header[0] === "Method" && header[1] === "Path") {
    for (const [method, rawPath, notes = ""] of body) {
      if (!METHOD_ORDER.includes(method)) {
        throw new Error(`unknown method ${method} in section "${section.title}"`);
      }
      routes.push({
        method,
        path: rawPath.replace(/^`|`$/g, ""),
        notes,
        servedBy: section.label,
      });
    }
  } else {
    extras.push({ title: section.title, header, rows: body });
  }
}

if (routes.length === 0) throw new Error(`no routes parsed from ${input}`);

function prefixOf(path: string): string {
  const segs = path.split("/").filter(Boolean);
  if (segs.length === 0) return "/";
  let take = 1;
  if (segs[0] === "api") take = /^v\d+$/.test(segs[1] ?? "") ? 3 : 2;
  const kept: string[] = [];
  for (const seg of segs.slice(0, take)) {
    if (seg.startsWith("{")) break;
    kept.push(seg);
  }
  return "/" + kept.join("/");
}

const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
const byPrefix = new Map<string, Route[]>();
for (const r of routes) {
  const p = prefixOf(r.path);
  if (!byPrefix.has(p)) byPrefix.set(p, []);
  byPrefix.get(p)!.push(r);
}
const groups = new Map<string, Route[]>();
const other: Route[] = [];
for (const p of [...byPrefix.keys()].sort(cmp)) {
  const list = byPrefix.get(p)!;
  if (list.length < MIN_GROUP) other.push(...list);
  else groups.set(p, list);
}
if (other.length > 0) groups.set(OTHER, other);

const sectionCounts = new Map<string, number>();
for (const r of routes) sectionCounts.set(r.servedBy, (sectionCounts.get(r.servedBy) ?? 0) + 1);

const out: string[] = [];
out.push(
  "---",
  'title: "REST API index"',
  'description: "Every HTTP and WebSocket route the ADOS Drone Agent serves, grouped by path prefix, with the listener that answers it and its auth notes."',
  'sidebarTitle: "REST API index"',
  'icon: "list"',
  "---",
  "",
  "{/* Generated by Documentation/scripts/gen-api-index.ts from ADOSDroneAgent/docs/api-surface.md. Do not edit by hand; run `npm --prefix scripts run gen:api` from Documentation/. */}",
  "",
  "This index is generated from the Drone Agent source. Its input is the agent's",
  "own route table, which a test in the agent keeps in step with the router, so",
  "every row here is a route the agent actually serves. For request and response",
  "shapes, authentication, and worked examples, see the",
  "[REST API guide](/drone-agent/rest-api).",
  "",
  "How to read the tables:",
  "",
  "- A `{name}` segment matches one path segment; `{*name}` matches the rest of the path.",
  "- Method `WS` marks a route that answers only a WebSocket upgrade.",
  '- **unauthenticated by design** marks a route that answers with no credential at all.',
  "- **relay-forbidden** marks a route the agent refuses when the request arrives through the cloud relay, so it only works from the local network.",
  "- A blank note means the route takes the normal auth of the listener that serves it.",
  "",
  "## Listeners",
  "",
  "| Served by | Routes |",
  "| --- | --- |",
);
for (const section of sections) {
  const n = sectionCounts.get(section.label);
  if (n) out.push(`| ${cell(section.label)} | ${n} |`);
}
out.push(`| **Total** | ${routes.length} |`, "");

for (const [key, list] of groups) {
  out.push(key === OTHER ? `## ${OTHER}` : `## \`${key}\``, "");
  if (key === OTHER) {
    out.push(`Prefixes with fewer than ${MIN_GROUP} routes.`, "");
  }
  out.push("| Method | Path | Served by | Notes |", "| --- | --- | --- | --- |");
  list.sort(
    (a, b) =>
      cmp(a.path, b.path) || METHOD_ORDER.indexOf(a.method) - METHOD_ORDER.indexOf(b.method),
  );
  for (const r of list) {
    out.push(
      `| ${r.method} | \`${r.path.replace(/\|/g, "\\|")}\` | ${cell(r.servedBy)} | ${cell(r.notes)} |`,
    );
  }
  out.push("");
}

for (const extra of extras) {
  out.push(`## ${cell(extra.title)}`, "");
  out.push(`| ${extra.header.map(cell).join(" | ")} |`);
  out.push(`| ${extra.header.map(() => "---").join(" | ")} |`);
  for (const row of extra.rows) out.push(`| ${row.map(cell).join(" | ")} |`);
  out.push("");
}

const text = out.join("\n").replace(/\n+$/, "\n");
if (/[\u2014]/.test(text)) throw new Error("output contains an em dash");
mkdirSync(dirname(OUTPUT), { recursive: true });
writeFileSync(OUTPUT, text, "utf-8");
console.log(`wrote ${OUTPUT}: ${routes.length} routes in ${groups.size} groups`);
